const input = $json.body ?? $json;
const dealId = input.deal_id ?? input.dealId;
const leadId = input.lead_id ?? input.leadId;
const propertyId = input.property_id ?? input.propertyId;
const providerMessageId = input.provider_message_id ?? input.providerMessageId;
const dispatchKey = input.provider_dispatch_idempotency_key ?? input.dispatch_idempotency_key ?? input.idempotency_key;
const status = String(input.provider_status ?? input.delivery_status ?? input.status ?? '').toLowerCase();
const channel = String(input.channel ?? '').toLowerCase();
const hasInboundResponse = Boolean(input.inbound_seller_response || input.seller_response || input.inbound_message);
const dnc = Boolean(input.dnc || input.do_not_contact || input.opted_out);
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const attempts = Number(input.attempts ?? 0);
const maxAttempts = Number(input.max_attempts ?? 5);
const identityValid = Boolean(dealId && leadId && propertyId && providerMessageId && dispatchKey && channel);
const terminalFailure = ['failed','bounced','rejected','undeliverable'].includes(status);
const acceptedDelivery = ['accepted','sent','delivered'].includes(status);
const duplicateKey = dispatchKey && providerMessageId && status
  ? `${dispatchKey}:delivery:${providerMessageId}:${status}`
  : null;
let decision = 'monitor';
let route = 'WF-361';
let reason = 'Delivery receipt is valid and seller response monitoring should remain active.';
if (dnc) { decision='hard_stop'; route='WF-126'; reason='DNC/opt-out is active; no further outbound communication is permitted.'; }
else if (blockers.length) { decision='blocked'; route='WF-126'; reason='Operational blockers prevent automated communication continuation.'; }
else if (!identityValid) { decision='reconcile'; route='WF-360'; reason='Required provider dispatch identity is missing; reconcile the dispatch record before proceeding.'; }
else if (hasInboundResponse) { decision='seller_response'; route='WF-342'; reason='Inbound seller response detected; route to AI response classification.'; }
else if (terminalFailure) { decision='delivery_failure'; route='WF-350'; reason='Provider delivery failed; route to controlled retry/re-engagement.'; }
else if (acceptedDelivery) { decision='monitor'; route='WF-361'; reason='Provider accepted/sent/delivered the message; activate seller response monitoring.'; }
else { decision='unknown_status'; route='WF-360'; reason='Provider status is not recognized; reconcile provider state before automated continuation.'; }
const result = {workflow:'WF-368',decision,route,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,provider_message_id:providerMessageId,provider_status:status,channel,attempts,max_attempts:maxAttempts,dnc,blockers,dispatch_idempotency_key:dispatchKey,delivery_idempotency_key:duplicateKey,duplicate_safe:Boolean(duplicateKey),identity_valid:identityValid,has_inbound_seller_response:hasInboundResponse,next_action:route==='WF-361'?'monitor_seller_response':route==='WF-342'?'classify_seller_response':route==='WF-350'?'controlled_retry_or_reengagement':route==='WF-126'?'human_control':'reconcile_provider_state',audit_event:'provider_delivery_receipt_seller_response_monitoring'};
return [{json:result}];
